import re
from functools import cmp_to_key
from typing import List


def _parse_version(raw: str):
    """
    Semantic Version 2.0.0'ı parse eder.

    Returns:
        (major, minor, patch, prerelease_tuple, build_str)
        prerelease_tuple: None (release) veya karşılaştırma için kullanılabilir tuple.
        build_str: derleme bilgisi (önceliği etkilemez, sadece tutulur).
    """
    if not isinstance(raw, str):
        raise ValueError(f"Geçersiz sürüm tipi: {type(raw)}")

    s = raw.strip()

    # Regex: optional v, 3 nums, optional pre, optional build
    m = re.fullmatch(
        r'v?(?P<major>0|[1-9]\d*)'
        r'\.(?P<minor>0|[1-9]\d*)'
        r'\.(?P<patch>0|[1-9]\d*)'
        r'(?:-(?P<pre>[0-9A-Za-z\-\\.]+))?'
        r'(\+(?P<build>[0-9A-Za-z\-\\.]+))?',
        s,
    )
    if not m:
        raise ValueError(f"Geçersiz sürüm metni: {raw!r}")

    major = int(m['major'])
    minor = int(m['minor'])
    patch = int(m['patch'])
    pre_str = m['pre']  # None veya string
    build_str = m['build']  # None veya string

    # Parse pre-release tokens
    pre = None
    if pre_str is not None and pre_str != '':
        # Split by dot, each token is either numeric or identifier
        tokens = pre_str.split('.')
        parsed_tokens = []
        for token in tokens:
            if token == '':
                raise ValueError(f"Ön sürüm token boş olamaz: {raw!r}")
            parsed_tokens.append(token)
        pre = parsed_tokens

    # Validate build identifier (alphanumeric + hyphens allowed, no empty tokens)
    if build_str is not None and build_str != '':
        build_tokens = build_str.split('.')
        for bt in build_tokens:
            if bt == '':
                raise ValueError(f"Build token boş olamaz: {raw!r}")

    return (major, minor, patch, pre, build_str)


def _pre_compare(tokens_a, tokens_b):
    """
    İki ön-sürüm token listesini karşılaştır.
    SemVer 3.9: numeric tokens are always lower precedence than alphanumeric.
    Fewer fields = lower precedence if all preceding fields are equal.
    """
    # No pre-release > has pre-release (release always wins)
    if tokens_a is None and tokens_b is None:
        return 0
    if tokens_a is None:
        return 1  # release > alpha
    if tokens_b is None:
        return -1  # alpha < release

    min_len = min(len(tokens_a), len(tokens_b))
    for i in range(min_len):
        a = tokens_a[i]
        b = tokens_b[i]

        a_is_num = a.isdigit()
        b_is_num = b.isdigit()

        if a_is_num and b_is_num:
            diff = int(a) - int(b)
            if diff != 0:
                return -1 if diff < 0 else 1
        elif a_is_num and not b_is_num:
            # numeric < identifier
            return -1
        elif not a_is_num and b_is_num:
            return 1
        else:
            # both strings
            if a < b:
                return -1
            elif a > b:
                return 1

    # All common fields equal, shorter list < longer list
    if len(tokens_a) < len(tokens_b):
        return -1
    elif len(tokens_a) > len(tokens_b):
        return 1
    return 0


def _cmp(a, b):
    """İki sürüm stringini karşılaştırır: -1, 0, 1."""
    va = _parse_version(a)
    vb = _parse_version(b)

    # Compare major.minor.patch
    for i in range(3):
        if va[i] < vb[i]:
            return -1
        if va[i] > vb[i]:
            return 1

    # Compare prerelease
    return _pre_compare(va[3], vb[3])


def compare(a: str, b: str) -> int:
    """a < b ise -1, eşit öncelikteyse 0, a > b ise 1 döndürür."""
    return _cmp(a, b)


def sort_versions(versions: list[str]) -> list[str]:
    """Önceliğe göre artan sıralı yeni liste döndürür.
    Eşit öncelikli sürümler girdideki sıralarını korusun (stable sort)."""
    indexed = list(enumerate(versions))
    stable_sorted = sorted(indexed, key=lambda ix: _parse_version(versions[ix[0]]))
    return [v for _, v in stable_sorted]

